css:
/* Dispense di Teoria (tcolorbox + Fira Sans + Latin Modern) /
:root {
    --bg: #e5e7eb;
    --surface: #ffffff;
    --ink: #111827;
    --ink-muted: #4b5563;
    --ink-subtle: #6b7280;
    --red-accent: #991b1b;
    --blue-accent: #1d4ed8;
    --green-accent: #15803d;
    --yellow-accent: #a16207;
    --gray-frame: #4b5563;
    --border: #d1d5db;
    --font-serif: 'Latin Modern Roman', 'CMU Serif', Georgia, serif;
    --font-sans: 'Fira Sans', -apple-system, BlinkMacSystemFont, sans-serif;
    --font-code: 'Fira Code', monospace;
}

 { box-sizing: border-box; }
html, body {
    margin: 0; padding: 0; width: 100%;
    background: var(--bg); color: var(--ink);
    font-family: var(--font-serif); font-size: 16px; line-height: 1.58;
}

body { display: flex; flex-direction: column; align-items: center; padding: 24px 14px; }

.article-wrapper {
    width: 100%; max-width: 794px; background: var(--surface);
    padding: 38px 46px; box-shadow: 0 10px 30px rgba(0,0,0,0.12);
    border: 1px solid #cbd5e1;
}

.top-nav { display: none; }

/* TikZ-inspired Chapter Header: Huge Red Number + Stacked Fira Sans Title/Subtitle /
.article-header {
    display: flex;
    flex-direction: row;
    align-items: flex-end;
    gap: 20px;
    text-align: left;
    margin-bottom: 24px;
    padding-bottom: 12px;
    border-bottom: 1px solid #e5e7eb;
}

.article-header[data-tag]:not([data-tag=

])::before {
    content: attr(data-tag);
    font-family: var(--font-sans);
    font-size: 64px;
    font-weight: 800;
    line-height: 0.88;
    color: var(--red-accent);
    flex-shrink: 0;
    letter-spacing: -0.03em;
}

.header-main-group {
    display: flex;
    flex-direction: column;
    gap: 3px;
}

.post-title {
    font-family: var(--font-sans);
    font-size: 25px;
    font-weight: 700;
    color: var(--ink);
    margin: 0;
    line-height: 1.18;
}

.subtitle {
    font-family: var(--font-sans);
    font-size: 18px;
    font-weight: 700;
    font-style: normal;
    color: #1f2937;
    margin: 0;
    line-height: 1.2;
}

.post-meta {
    font-family: var(--font-sans);
    font-size: 11.5px;
    color: var(--ink-muted);
    display: flex;
    justify-content: flex-start;
    gap: 14px;
    margin-top: 4px;
}

.article-content { text-align: justify; }
.article-content p { margin: 0 0 10px 0; }

.article-content h2 {
    font-family: var(--font-sans);
    font-size: 18.5px;
    font-weight: 700;
    color: var(--red-accent);
    border-bottom: 1.5px solid #fecaca;
    padding-bottom: 3px;
    margin: 24px 0 12px 0;
}

.article-content h3 {
    font-family: var(--font-sans);
    font-size: 16px;
    font-weight: 700;
    color: var(--ink);
    margin: 18px 0 8px 0;
}

/ tcolorbox Style: Floating Top-Left Boxed Title + Sharp Southwest Corner /
.clawri-thm {
    position: relative;
    margin: 24px 0 18px 0 !important;
    padding: 16px 14px 11px 14px !important;
    border-radius: 0 4px 4px 4px !important;
    border: 1px solid var(--blue-accent) !important;
    background: #eff6ff !important;
}

.clawri-thm-title {
    position: absolute;
    top: -11px;
    left: 8px;
    padding: 1px 9px;
    font-family: var(--font-sans);
    font-size: 12.5px;
    font-weight: 700;
    line-height: 1.35;
    background: #dbeafe;
    color: var(--blue-accent);
    border: 1px solid var(--blue-accent);
    border-radius: 0;
}

/ Teorema & Corollario -> Blue /
.clawri-theorem, .clawri-corollary {
    background: #eff6ff !important;
    border-color: var(--blue-accent) !important;
}
.clawri-theorem .clawri-thm-title, .clawri-corollary .clawri-thm-title {
    background: #dbeafe;
    color: var(--blue-accent);
    border-color: var(--blue-accent);
}

/ Definizione -> Red /
.clawri-definition {
    background: #fef2f2 !important;
    border-color: var(--red-accent) !important;
}
.clawri-definition .clawri-thm-title {
    background: #fee2e2;
    color: var(--red-accent);
    border-color: var(--red-accent);
}

/ Proposizione -> Green /
.clawri-proposition {
    background: #f0fdf4 !important;
    border-color: var(--green-accent) !important;
}
.clawri-proposition .clawri-thm-title {
    background: #dcfce7;
    color: var(--green-accent);
    border-color: var(--green-accent);
}

/ Lemma -> Yellow/Amber /
.clawri-lemma {
    background: #fefce8 !important;
    border-color: var(--yellow-accent) !important;
}
.clawri-lemma .clawri-thm-title {
    background: #fef9c3;
    color: var(--yellow-accent);
    border-color: var(--yellow-accent);
}

/ Curiosità & Video Box -> Gray tcolorbox with Top-Left Small-Caps Badge /
.clawri-box {
    position: relative;
    margin: 24px 0 18px 0 !important;
    padding: 16px 14px 11px 14px !important;
    border: 1px solid var(--gray-frame) !important;
    background: #f9fafb !important;
    color: var(--ink) !important;
    border-radius: 0 4px 4px 4px !important;
}

.clawri-box-title {
    position: absolute;
    top: -11px;
    left: 16px;
    padding: 1px 9px;
    font-family: var(--font-sans);
    font-size: 12px;
    font-weight: 700;
    font-variant: small-caps;
    letter-spacing: 0.03em;
    background: #e5e7eb;
    color: #111827;
    border: 1px solid var(--gray-frame);
    margin: 0 !important;
}

/ Solution Box -> Gray Fill + Thick Red Left Rule /
.clawri-solution {
    background: #f3f4f6 !important;
    border: none !important;
    border-left: 5px solid var(--red-accent) !important;
    border-radius: 0 !important;
    padding: 10px 14px !important;
    margin: 14px 0 18px 0 !important;
}

.clawri-solution summary {
    font-family: var(--font-sans);
    font-size: 13px;
    color: var(--red-accent);
}

/ Quotebox2 -> White Box, Red Border, Oversized Red Quotation Marks */
blockquote.quote-box {
    position: relative;
    background: #ffffff !important;
    border: 1.5px solid var(--red-accent) !important;
    border-radius: 0 !important;
    padding: 14px 26px !important;
    margin: 20px 0 !important;
    color: var(--ink) !important;
}

blockquote.quote-box::before {
    content:

;
    position: absolute;
    top: -6px;
    left: 5px;
    font-family: Georgia, serif;
    font-size: 40px;
    line-height: 1;
    color: var(--red-accent);
    font-weight: 700;
}

blockquote.quote-box::after {
    content:

;
    position: absolute;
    bottom: -20px;
    right: 6px;
    font-family: Georgia, serif;
    font-size: 40px;
    line-height: 1;
    color: var(--red-accent);
    font-weight: 700;
}

.sidenote-desktop { display: none !important; }
.article-footer { display: none; }

@page { size: A4; margin: 12mm; }
@media print {
    body { background: #fff; padding: 0; }
    .article-wrapper { box-shadow: none; border: none; padding: 0; max-width: 100%; }
    .clawri-pdf-btn-wrap { display: none !important; }
}
